package com.smartbank.service;
import com.smartbank.entity.*; import com.smartbank.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class BankingServiceTest {
 @Mock AccountRepository accounts; @Mock TransactionRepository transactions; @Mock UserRepository users; @Mock NotificationRepository notifications; BankingService service;
 @BeforeEach void setup(){service=new BankingService(accounts,transactions,users,notifications);}
 BankAccount account(long id,String email,String number,String balance){User u=new User();u.id=id;u.email=email;BankAccount a=new BankAccount();a.id=id;a.user=u;a.accountNumber=number;a.balance=new BigDecimal(balance);a.status="ACTIVE";a.accountType="SAVINGS";return a;}
 @Test void depositUpdatesBalanceAndRecordsTransaction(){var a=account(1,"a@test.test","SB0001","25.00");when(accounts.findLockedById(1L)).thenReturn(Optional.of(a));var result=service.deposit("a@test.test",1L,new BigDecimal("12.50"),"Top up");assertEquals(new BigDecimal("37.50"),result.balance());verify(transactions).save(argThat(t->t.type.equals("DEPOSIT")&&t.amount.equals(new BigDecimal("12.50"))));}
 @Test void withdrawalRejectsInsufficientFunds(){var a=account(1,"a@test.test","SB0001","10.00");when(accounts.findLockedById(1L)).thenReturn(Optional.of(a));assertThrows(ResponseStatusException.class,()->service.withdraw("a@test.test",1L,new BigDecimal("10.01"),null));assertEquals(new BigDecimal("10.00"),a.balance);verify(transactions,never()).save(any());}
 @Test void customerCannotUseAnotherCustomersAccount(){var a=account(1,"owner@test.test","SB0001","50.00");when(accounts.findLockedById(1L)).thenReturn(Optional.of(a));assertThrows(ResponseStatusException.class,()->service.deposit("other@test.test",1L,BigDecimal.ONE,null));verify(transactions,never()).save(any());}
 @Test void transferDebitsAndCreditsBothAccountsTogether(){var sender=account(1,"a@test.test","SB0001","100.00");var recipient=account(2,"b@test.test","SB0002","5.00");when(accounts.findLockedById(1L)).thenReturn(Optional.of(sender));when(accounts.findLockedByNumber("SB0002")).thenReturn(Optional.of(recipient));var result=service.transfer("a@test.test",1L,"SB0002",new BigDecimal("30.00"),"Rent");assertEquals(new BigDecimal("70.00"),result.balance());assertEquals(new BigDecimal("35.00"),recipient.balance);verify(transactions,times(2)).save(any(BankTransaction.class));}
 @Test void transferRejectsSelfTransfer(){var a=account(1,"a@test.test","SB0001","100.00");when(accounts.findLockedById(1L)).thenReturn(Optional.of(a));when(accounts.findLockedByNumber("SB0001")).thenReturn(Optional.of(a));assertThrows(ResponseStatusException.class,()->service.transfer("a@test.test",1L,"SB0001",new BigDecimal("5.00"),null));assertEquals(new BigDecimal("100.00"),a.balance);verify(transactions,never()).save(any());}
}
